// Store the exact generated bytes separately from small localStorage snapshots.
// A refreshed Thank You screen reuses the same PDF for View and Download.
const database = () => new Promise((resolve, reject) => {
  const request = indexedDB.open('the-phallus.order-pdfs', 1);
  request.onupgradeneeded = () => request.result.createObjectStore('pdfs');
  request.onsuccess = () => resolve(request.result);
  request.onerror = () => reject(request.error);
});
async function storedPdf(id, blob) {
  const db = await database();
  try {
    return await new Promise((resolve,reject) => {
      const tx = db.transaction('pdfs', blob ? 'readwrite' : 'readonly');
      const store = tx.objectStore('pdfs'), request = blob ? store.put(blob,id) : store.get(id);
      tx.oncomplete = () => resolve(request.result);
      tx.onerror = () => reject(tx.error); tx.onabort = () => reject(tx.error);
    });
  } finally { db.close(); }
}
const cache = new Map();
export function completedOrderPdf(order, onProgress = () => {}) {
  if (cache.has(order.id)) return cache.get(order.id);
  const promise = (async () => {
    let blob;
    try { blob = await storedPdf(order.id); } catch {}
    if (!blob) {
      const bytes = await new Promise((resolve,reject) => {
        const worker = new Worker(new URL('./pdf-worker.js',import.meta.url),{type:'module'});
        worker.onmessage = ({data}) => {
          if (data.progress) { onProgress(data.progress); return; }
          worker.terminate(); data.error ? reject(new Error(data.error)) : resolve(data.bytes);
        };
        worker.onerror = () => { worker.terminate(); reject(new Error('PDF generation failed. Please try again.')); };
        worker.postMessage({order});
      });
      blob = new Blob([bytes],{type:'application/pdf'});
      try { await storedPdf(order.id,blob); } catch {} // In-memory reuse remains available.
    }
    return {url:URL.createObjectURL(blob),filename:'THE_PHALLUS_ORDER.pdf'};
  })();
  cache.set(order.id,promise);
  promise.catch(() => cache.delete(order.id));
  return promise;
}
window.addEventListener('beforeunload', () => {
  for (const promise of cache.values()) promise.then(result => URL.revokeObjectURL(result.url));
});
